mapper.sql:
where 1=1

		and crmp_llave = #{key}


		and crmp_estado = #{state}


		and crmp_cuenta = #{account}


		and nrmp_nivel = #{level}


		and drmp_fecha = #{mapDate}


		and nrmp_ano = #{year}


		and nrmp_mes = #{month}


		and nrmp_dia = #{day}


		and nrmp_hora = #{hour}


		and nrmp_minuto = #{minute}


		and nrmp_cantidad = #{quantity}


		and mrmp_saldoanterior = #{lastBalance}


		and mrmp_positivo = #{positive}


		and mrmp_negativo = #{negative}


		and mrmp_valor = #{value}

mapper.select:
update account.mapa_resultados_rmp
	set
		mrmp_saldoanterior = mrmp_saldoanterior + #{value},
		mrmp_saldosiguiente = mrmp_saldosiguiente + #{value}
where
	 nrmp_nivel = #{level} and drmp_fechainicio > #{startDate} and crmp_cuenta = #{account}
